module RDDensityTest

using Test
using KernelSmoothing

# reference values from rddensity 3.0, generated by data/rddensity_golden.R
include(joinpath(@__DIR__, "data", "rddensity_golden.jl"))

# 600 observations without ties (with a constant of 30 bits, so that R computes the
# same values), the same data with a density that jumps at 0, and with mass points
const I = 1:600
const X = 2 .* mod.(I .* (round(0.6180339887498949 * 2^30) / 2^30), 1) .- 1
const DATA = Dict("x" => X, "xj" => ifelse.(X .< 0, X, X .^ 2), "xm" => round.(10 .* X) ./ 10)
const KERNELS = Dict("triangular" => TriangularKernel(), "uniform" => UniformKernel(), "epanechnikov" => EpanechnikovKernel())

@testset "agrees with rddensity" begin
  for c in RDDENSITY
    m = fit(DensityDiscontinuity, DATA[c.x]; cutoff = c.c, degree = c.p, kernel = KERNELS[c.kernel],
            vce = Symbol(c.vce), restricted = c.fitselect == "restricted", masspoints = c.masspoints,
            bandwidth = c.h === nothing ? RDDensityOptimal(Symbol(c.bwselect)) : c.h)
    @test [m.h...] ≈ c.hused rtol = 1e-8
    @test [m.nh...] == c.nh
    t = coeftable(m)
    @test t.estimate ≈ c.hat rtol = 1e-8
    @test t.se ≈ c.sd rtol = 1e-8
    @test m.statistic ≈ c.t rtol = 1e-8
    @test m.pvalue ≈ c.pvalue rtol = 1e-8
    @test m.binomial.left ≈ c.bino_left && m.binomial.right ≈ c.bino_right
    @test m.binomial.nleft == c.bino_nl && m.binomial.nright == c.bino_nr
    @test m.binomial.pvalue ≈ c.bino_p rtol = 1e-10
    if haskey(c, :bw)
      d = m.selection.details
      @test [d.left, d.right, d.diff, d.sum] ≈ c.bw rtol = 1e-8
    end
  end
end

@testset "interface" begin
  m = fit(DensityDiscontinuity, DATA["xj"])
  @test m.selection.rule == RDDensityOptimal(:comb)
  @test coef(m) == [m.density[2] - m.density[1]] && stderror(m) == [m.se[3]]
  @test m.statistic ≈ coef(m)[1] / stderror(m)[1]
  @test m.pvalue < 0.01   # the density jumps
  @test confint(m)[2] - confint(m)[1] ≈ 2 * 1.959963984540054 * m.se[3]
  t = coeftable(m)
  @test t.side == ["left", "right", "jump"] && t.estimate[3] ≈ coef(m)[1]
  @test nobs(m) == 600 && bandwidth(m) == m.h
  # the selected bandwidths given back reproduce the fit
  m2 = fit(DensityDiscontinuity, DATA["xj"]; bandwidth = m.h)
  @test m2.statistic ≈ m.statistic && m2.selection.rule === nothing
  @test fit(DensityDiscontinuity, X).pvalue > 0.5   # no jump
  @test startswith(sprint(show, m), "DensityDiscontinuity(cutoff 0.0, 600 observations, p-value ")
  @test occursin("test of continuity", sprint(show, MIME"text/plain"(), m))
  @test sprint(show, RDDensityOptimal(:diff)) == "RDDensityOptimal(:diff)"
  @test fit(DensityDiscontinuity, DATA["xm"]).masspoints && !fit(DensityDiscontinuity, X).masspoints
  @test length(fit(DensityDiscontinuity, X; binomialwindows = 1).binomial.pvalue) == 1
  @inferred fit(DensityDiscontinuity, X)
end

@testset "binomial test" begin
  # R's binom.test(x, n)$p.value
  @test KernelSmoothing._binomtest(10, 20) == 1
  @test KernelSmoothing._binomtest(3, 20) ≈ 0.0025768280029296875
  @test KernelSmoothing._binomtest(17, 20) ≈ 0.0025768280029296875
  @test KernelSmoothing._binomtest(0, 0) == 1
end

@testset "errors" begin
  @test_throws ArgumentError fit(DensityDiscontinuity, X; degree = 0)
  @test_throws ArgumentError fit(DensityDiscontinuity, X; degree = 8)
  @test_throws ArgumentError fit(DensityDiscontinuity, X; vce = :hc0)
  @test_throws ArgumentError fit(DensityDiscontinuity, X; cutoff = 2)
  @test_throws ArgumentError fit(DensityDiscontinuity, X; kernel = GaussianKernel())
  @test_throws ArgumentError fit(DensityDiscontinuity, X; restricted = true, bandwidth = RDDensityOptimal(:each))
  @test_throws ArgumentError fit(DensityDiscontinuity, X; restricted = true, bandwidth = (0.3, 0.4))
  @test_throws ArgumentError fit(DensityDiscontinuity, X; bandwidth = MSEOptimal())
  @test_throws ArgumentError fit(DensityDiscontinuity, X; minobs = -1)
  @test_throws ArgumentError fit(DensityDiscontinuity, X; binomialn = 0)
  @test_throws ArgumentError RDDensityOptimal(:mserd)
  @test_throws ArgumentError fit(KDE, X; bandwidth = RDDensityOptimal())
end

end
